    }

    /** Applies one backend-returned conversation without another persistence round trip. */
    updateConversation(conversation: AgentConversation) {
        this.validateSelection(conversation)
        const conversations = this.snapshot.conversations.some(({ path }) => path === conversation.path)
            ? this.snapshot.conversations.map((current) => (current.path === conversation.path ? conversation : current))
            : [...this.snapshot.conversations, conversation]
        const selectedConversation = this.snapshot.selectedConversation?.path === conversation.path
            ? conversation
            : this.snapshot.selectedConversation
        this.setSnapshot({ ...this.snapshot, conversations, selectedConversation })
    }

    private clearPromptDraftWhenIdle() {
        const boundRunId = this.bindingStore.getSnapshot()
        const run = boundRunId ? actionRunRegistry.getRunStore(boundRunId)?.getSnapshot() ?? null : null
        const runActive = run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput'
        if (runActive) return

        actionPromptDraftService.discardUneditedDraft(this.actionId, this.context, this.bindingStore.getSnapshot())
    }

    private validateSelection(conversation: AgentConversation) {
        if (!belongsToContext(conversation, this.context)) throw new Error('Selected agent conversation belongs to another context')
        if (conversation.actionId !== this.actionId) throw new Error('Selected agent conversation belongs to another action')
    }

    private setSnapshot(snapshot: ActionConversationSnapshot) {
        this.snapshot = snapshot
        for (const listener of this.listeners) listener()
    }
}

import { actionRunRegistry } from '../../../../services/actions/action_run_registry'
import type { ActionContext } from '../../../../data/action_context'

const BINDING_CHANGED_EVENT = 'bindingChanged'

/** Owns run selected by one popup action/context runtime. Null selects New conversation. */
export class ActionRunBindingStore extends EventTarget {
    private boundRunId: string | null
    private selectionConfigured: boolean
    private unsubscribeInitialRun: (() => void) | null = null
    private unsubscribeRun: (() => void) | null

    constructor(initialRunId: string | null) {
        super()
        this.boundRunId = initialRunId
        this.selectionConfigured = initialRunId !== null
        this.unsubscribeRun = initialRunId ? actionRunRegistry.subscribeRun(initialRunId, () => undefined) : null
    }

    readonly getSnapshot = () => this.boundRunId

    readonly subscribe = (listener: () => void) => {
        this.addEventListener(BINDING_CHANGED_EVENT, listener)

        return () => this.removeEventListener(BINDING_CHANGED_EVENT, listener)
    }

    setRunId(runId: string | null) {
        this.selectionConfigured = true
        this.unsubscribeInitialRun?.()
        this.unsubscribeInitialRun = null
        if (this.boundRunId === runId) return

        this.unsubscribeRun?.()
        this.boundRunId = runId
        this.unsubscribeRun = runId ? actionRunRegistry.subscribeRun(runId, () => undefined) : null
        this.dispatchEvent(new Event(BINDING_CHANGED_EVENT))
    }

    adoptInitialRun(runId: string | null) {
        if (this.selectionConfigured || runId === null) return

        this.selectionConfigured = true
        this.unsubscribeInitialRun?.()
        this.unsubscribeInitialRun = null
        this.boundRunId = runId
        this.unsubscribeRun = actionRunRegistry.subscribeRun(runId, () => undefined)
        this.dispatchEvent(new Event(BINDING_CHANGED_EVENT))
    }

    trackInitialRun(actionId: string, context: ActionContext) {
        if (this.selectionConfigured || this.unsubscribeInitialRun) return

        this.unsubscribeInitialRun = actionRunRegistry.subscribeActionRun(actionId, context, () => {
            const runId = actionRunRegistry.getActionRunStore(actionId, context)?.getSnapshot().runId ?? null
            this.adoptInitialRun(runId)
        })
    }

    dispose() {
        this.unsubscribeInitialRun?.()
        this.unsubscribeInitialRun = null
        this.unsubscribeRun?.()
        this.unsubscribeRun = null
    }
}

import { useCallback, useSyncExternalStore } from 'react'
import { actionContextIdentity, type ActionContext } from '../../data/action_context'
import { actionRunRegistry, type ActionRun, type ActionRunStore } from '../../services/actions/action_run_registry'
import type { ActionRunBindingStore } from '../actions/run/state/action_run_binding_store'

const EMPTY_ACTIVE_RUNS: ReturnType<typeof actionRunRegistry.getGlobalActiveSnapshot> = []
const EMPTY_RUN_STORES: ActionRunStore[] = []
const subscribeEmpty = () => () => undefined
const getNullSnapshot = () => null

function useRunStore<T>(store: ActionRunStore | null, selector: (run: ActionRun | null) => T) {
    return useSyncExternalStore(
        store?.subscribe ?? subscribeEmpty,
        () => selector(store?.getSnapshot() ?? null),
        () => selector(null),
    )
}

function useActionRunStore(actionId: string, context: ActionContext) {
    const contextIdentity = actionContextIdentity(context)
    const subscribe = useCallback(
        (listener: () => void) => actionRunRegistry.subscribeActionRunByKey(actionId, contextIdentity, listener),
        [actionId, contextIdentity],
    )
    const getSnapshot = useCallback(
        () => actionRunRegistry.getActionRunStoreByKey(actionId, contextIdentity),
        [actionId, contextIdentity],
    )
    const store = useSyncExternalStore(
        subscribe,
        getSnapshot,
        getNullSnapshot,
    )

    return store
}

/** Subscribe to only the latest run bound to one root action and context. */
export function useActionRun(actionId: string, context: ActionContext) {
    const store = useActionRunStore(actionId, context)

    return useRunStore(store, (run) => run)
}

/** Subscribe to one selected value from a scoped action run. */
export function useActionRunSelector<T>(actionId: string, context: ActionContext, selector: (run: ActionRun | null) => T) {
    const store = useActionRunStore(actionId, context)

    return useRunStore(store, selector)
}

/** Subscribe to one selected value from a run identified by runId. */
export function useRunSelector<T>(runId: string | null, selector: (run: ActionRun | null) => T) {
    const subscribe = useCallback(
        (listener: () => void) => runId ? actionRunRegistry.subscribeRun(runId, listener) : subscribeEmpty(),
        [runId],
    )
    const getSnapshot = useCallback(
        () => selector(runId ? actionRunRegistry.getRunStore(runId)?.getSnapshot() ?? null : null),
        [runId, selector],
    )

    return useSyncExternalStore(subscribe, getSnapshot, () => selector(null))
}

/** Subscribe to runId selected by one popup runtime. */
export function useBoundRunId(bindingStore: ActionRunBindingStore) {
    return useSyncExternalStore(bindingStore.subscribe, bindingStore.getSnapshot, bindingStore.getSnapshot)
}

/** Subscribe to all live run stores for one root action and context. */
export function useActionRunStores(actionId: string, context: ActionContext) {
    const contextIdentity = actionContextIdentity(context)
    const subscribe = useCallback(
        (listener: () => void) => actionRunRegistry.subscribeActionRunByKey(actionId, contextIdentity, listener),
        [actionId, contextIdentity],
    )
    const getSnapshot = useCallback(
        () => actionRunRegistry.getActionRunStoresByKey(actionId, contextIdentity),
        [actionId, contextIdentity],
    )

    return useSyncExternalStore(subscribe, getSnapshot, () => EMPTY_RUN_STORES)
}

/** Subscribe to active run status summaries for one context. */
export function useActiveActionRunsForContext(context: ActionContext) {
    const contextIdentity = actionContextIdentity(context)
    const subscribe = useCallback(
        (listener: () => void) => actionRunRegistry.subscribeContextActiveByKey(contextIdentity, listener),
        [contextIdentity],
    )
    const getSnapshot = useCallback(
        () => actionRunRegistry.getContextActiveSnapshotByKey(contextIdentity),
        [contextIdentity],
    )

    return useSyncExternalStore(
        subscribe,
        getSnapshot,
        () => EMPTY_ACTIVE_RUNS,
    )
}

export function useRunningActionForContext(context: ActionContext) {
    return useActiveActionRunsForContext(context)[0] ?? null
}

/** Subscribe to the global active-run aggregate used by the global indicator. */
export function useActiveActionRuns() {
    return useSyncExternalStore(
        actionRunRegistry.subscribeGlobalActive,
        actionRunRegistry.getGlobalActiveSnapshot,
        actionRunRegistry.getGlobalActiveSnapshot,
    )
}

